mapper.insert:

	SELECT NVL(MAX(REPORT_NO), 0)+1
	FROM MEMBER_REPORT

INSERT INTO MEMBER_REPORT(
		REPORT_NO
		, MEMBER_ID
		, REPORT_TYPE
		, CONTENTS_TYPE
		, CONTENTS_NO
		, CONTENT
		, REPORTER_ID
)
SELECT
		#{reportNo}
		, #{memberId}
		, #{reportType}
		, #{contentsType}
		, #{contentsNo}
		, #{content}
		, #{reporterId}
FROM dual
WHERE NOT EXISTS(SELECT *
		FROM MEMBER_REPORT
		WHERE CONTENTS_NO = #{contentsNo}
		and REPORTER_ID = #{reporterId})
